def minSwaps(self, grid: List[List[int]]) -> int:
    n = len(grid)
    zeros = []
    for row in grid:
        count = 0
        for i in range(n - 1, -1, -1):
            if row[i] == 0:
                count += 1
            else:
                break
        zeros.append(count)

    swaps = 0
    for i in range(n):
        if zeros[i] >= n - 1 - i:
            continue

        for j in range(i + 1, n):
            if zeros[j] >= n - 1 - i:
                for k in range(j, i, -1):
                    zeros[k], zeros[k-1] = zeros[k-1], zeros[k]
                    swaps += 1
                break
        else:
            return -1

    return swaps

def mix(s1, s2):
    counts1 = {}
    counts2 = {}

    for char in s1:
        if 'a' <= char <= 'z':
            counts1[char] = counts1.get(char, 0) + 1

    for char in s2:
        if 'a' <= char <= 'z':
            counts2[char] = counts2.get(char, 0) + 1

    result = []
    for char in set(counts1.keys()) | set(counts2.keys()):
        count1 = counts1.get(char, 0)
        count2 = counts2.get(char, 0)
        max_count = max(count1, count2)

        if max_count > 1:
            if count1 > count2:
                result.append(('1', char * count1))
            elif count2 > count1:
                result.append(('2', char * count2))
            else:
                result.append(('=', char * count1))

    result.sort(key=lambda x: (-len(x[1]), x[0], x[1]))

    return '/'.join(f'{prefix}:{chars}' for prefix, chars in result)

def containsCycle(self, grid: List[List[str]]) -> bool:
    m = len(grid)
    n = len(grid[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(i, j, parent_i, parent_j, char):
        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] != char:
            return False
        if visited[i][j]:
            return True

        visited[i][j] = True

        # Check up
        if i - 1 >= 0 and (i - 1 != parent_i or j != parent_j):
            if dfs(i - 1, j, i, j, char):
                return True

        # Check down
        if i + 1 < m and (i + 1 != parent_i or j != parent_j):
            if dfs(i + 1, j, i, j, char):
                return True

        # Check left
        if j - 1 >= 0 and (i != parent_i or j - 1 != parent_j):
            if dfs(i, j - 1, i, j, char):
                return True

        # Check right
        if j + 1 < n and (i != parent_i or j + 1 != parent_j):
            if dfs(i, j + 1, i, j, char):
                return True

        return False

    for i in range(m):
        for j in range(n):
            if not visited[i][j]:
                if dfs(i, j, -1, -1, grid[i][j]):
                    return True

    return False

