class Solution:
    def numPermsDISequence(self, S: str) -> int:
        n = len(S)
        dp = [[0] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        MOD = 10**9 + 7

        for i in range(1, n + 1):
            new_dp = [[0] * (n + 1) for _ in range(n + 1)]
            for j in range(i + 1):
                if S[i - 1] == 'I':
                    for k in range(j):
                        new_dp[i][j] = (new_dp[i][j] + dp[i - 1][k]) % MOD
                else:
                    for k in range(j, i):
                        new_dp[i][j] = (new_dp[i][j] + dp[i - 1][k]) % MOD
            dp = new_dp

        ans = 0
        for j in range(n + 1):
            ans = (ans + dp[n][j]) % MOD
        return ans

