class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        pos, neg, mul = 0, 0, 0
        while target > 0:
            target, rem = divmod(target, x)
            if rem == 0:
                neg, pos = pos, neg
            elif rem == 1:
                neg, pos = pos + mul, neg + mul + 1
            elif rem == x - 1:
                neg, pos = pos + mul + 1, neg + mul
                target += 1
            else:
                pos_cost = mul * rem + min(rem, 1 + x - rem) + pos
                neg_cost = mul * (x - rem) + min(rem + 1, x - rem - 1 + 1) + neg
                pos = min(pos_cost, neg_cost + 1)
                neg = min(neg_cost, pos_cost + 1)
            mul += 1
        return min(pos, neg + mul) - 1

