class Solution:
    def minimumTotal(self, triangle: List[List[int]]) -> int:
        n = len(triangle)
        if n == 0:
            return 0

        dp = triangle[0]

        for i in range(1, n):
            new_dp = [0] * (i + 1)
            for j in range(i + 1):
                if j == 0:
                    new_dp[j] = dp[j] + triangle[i][j]
                elif j == i:
                    new_dp[j] = dp[j-1] + triangle[i][j]
                else:
                    new_dp[j] = min(dp[j-1], dp[j]) + triangle[i][j]
            dp = new_dp

        return min(dp)

class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        num_set = set(nums)
        longest_streak = 0

        for n in nums:
            if (n - 1) not in num_set:
                current_num = n
                current_streak = 1

                while (current_num + 1) in num_set:
                    current_num += 1
                    current_streak += 1

                longest_streak = max(longest_streak, current_streak)

        return longest_streak
